 let mut ticket=caller.native(g,|control|{assert!(control.prepare_work(1).unwrap());control.admit_turn_capacity(g.maximum_capacity_bytes).unwrap();control.charge(d.capacity_bytes).unwrap();let mut value=Some(7u64);let(turn,_)=with_effect(g,1<<20,&mut None,|effect|semio_framework_value::retirement::admit_owned_retirement(&mut value,effect));control.commit_work(turn.work).unwrap();let(owner,p)=turn.result.unwrap().unwrap();(Some(owner),p,u64::try_from(turn.work).unwrap())});
 for _ in 0..1000{if ticket.as_ref().unwrap().terminal_is_empty(){break}let d=semio_framework_value::factory_ticket_demands(ticket.as_ref().unwrap(),4096).unwrap();let g=grant(d);{let turn=close_ticket(&mut caller,&mut ticket,g,OriginalLawCaller::WORK,original_mode).unwrap();turn.result.unwrap();};}
 assert!(ticket.as_ref().unwrap().terminal_is_empty());let d=semio_framework_value::factory_ticket_demands(ticket.as_ref().unwrap(),4096).unwrap();let g=grant(d);
 {let turn=close_ticket(&mut caller,&mut ticket,g,OriginalLawCaller::STARVED,original_mode).unwrap();assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),RetainedCloneProgress::default());};assert!(ticket.is_some());
