struct RefusingClose{primary:Option<ValueError>,done:bool}
impl ErasedSnapshotRetirement for RefusingClose{
 fn next_computational_work(&self,_:usize)->Result<u64,ValueError>{Ok(u64::from(!self.done))}
 fn close_step(&mut self,effect:Effect<'_,'_>)->semio_framework_value::OriginalRetirementPoll{type Exit=semio_framework_value::RetirementPollExit;let result=(||->Result<RetainedCloneStep,Exit>{if let Some(primary)=self.primary.take(){std::hint::black_box(1u8);std::hint::black_box(2u8);Exit::pay(effect,2)?;return Err(primary.into())}self.done=true;Exit::pay(effect,1)?;Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,..Default::default()}))})();Exit::settle(effect,result)}
 fn terminal_is_empty(&self)->bool{self.done}
 fn next_copy_byte_demand(&self)->Result<usize,ValueError>{Ok(0)}
 fn next_capacity_byte_demand(&self,_:usize)->Result<usize,ValueError>{Ok(0)}
 fn next_release_byte_demand(&self)->Result<usize,ValueError>{Ok(0)}
 fn next_depth_demand(&self)->Result<usize,ValueError>{Ok(1)}
}
