 for original_mode in [false,true]{let mut caller=OriginalLawCaller::new();caller.prepare_failure_storage();let error=ValueError::new(ValueRefusalKind::InvalidValue,law["primary"].as_str().unwrap().to_owned());let pointer=error.message.as_ptr();let d=RetirementDemand{capacity_bytes:size_of::<RefusingClose>(),depth:1,..Default::default()};let g=grant(d);
 let mut ticket:Option<Box<dyn ErasedSnapshotRetirement>>=caller.native(g,|control|{assert!(control.prepare_work(1).unwrap());control.admit_turn_capacity(g.maximum_capacity_bytes).unwrap();control.charge(d.capacity_bytes).unwrap();let ticket:Box<dyn ErasedSnapshotRetirement>=Box::new(RefusingClose{primary:Some(error),done:false});control.commit_work(1).unwrap();(Some(ticket),RetainedCloneProgress{copied_items:1,retained_capacity_bytes:d.capacity_bytes,..Default::default()},1)});
 let d=semio_framework_value::factory_ticket_demands(ticket.as_ref().unwrap(),4096).unwrap();let g=grant(d);let failure={let turn=close_ticket(&mut caller,&mut ticket,g,OriginalLawCaller::WORK,original_mode).unwrap();assert_eq!(turn.work,u128::from(law["actualWork"].as_u64().unwrap()));turn.result.unwrap_err()};
 assert_eq!(failure.primary().unwrap().message.as_ptr(),pointer);assert_eq!(failure.work_refusal().unwrap().message,law["workRefusal"].as_str().unwrap());caller.close(failure);
 for _ in 0..32{if ticket.is_none(){break}let d=semio_framework_value::factory_ticket_demands(ticket.as_ref().unwrap(),4096).unwrap();let g=grant(d);{let turn=close_ticket(&mut caller,&mut ticket,g,OriginalLawCaller::WORK,original_mode).unwrap();turn.result.unwrap();};}assert!(ticket.is_none());caller.finish();}
