fn paged_semantic_projection_places_boxed_output_under_the_original_grant(){
 let work:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/⛽️work.json")).unwrap();let projection=PagedProjection::<BoxedSnapshot>::default();assert_eq!(projection.birth_work_demand().unwrap(),work["declaredWork"]["projectionBirth"].as_u64().unwrap());assert!(projection.take_work_demand().is_err());let projection=ClonedProjection::<u64>::new(RetainedCloneBirthDemand{capacity_bytes:0,depth:1});assert_eq!(projection.take_work_demand().unwrap(),work["declaredWork"]["retainedCloneTake"].as_u64().unwrap());
 use super::drivers::PagedProjection;
 let law:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/📽️projection.json")).unwrap();
 for row in law["cases"].as_array().unwrap(){
  let input=BoxedSnapshot{value:row["value"].as_u64().unwrap()};let d=RetainedCloneSource::<BoxedSnapshot>::owned_constructor_demand::<()>();
  let mut source=admit_source(input);
  let mut projection=PagedProjection::<BoxedSnapshot>::default();{let g=grant(projection.birth_demand());fx(g,|e|projection.begin(e)).unwrap();}
  for turn in 0..1000{let d=projection.demands(source.borrow(),4096,OriginalLawCaller::WORK).unwrap();let g=grant(d);let((step,heap),_)=with_effect(g,1<<20,&mut None,|e|observe(||projection.advance(source.borrow(),4096,e).unwrap()));assert!(step.progress().fits(g));assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress().retained_capacity_bytes,step.progress().released_bytes));if matches!(step,RetainedCloneStep::Complete(_)){break}assert!(turn<999)}
  let d=projection.take_demand().unwrap();let g=grant(d);assert_eq!(d.release_bytes,size_of::<BoxedSnapshot>());
  let short=RetainedCloneGrant{maximum_release_bytes:d.release_bytes-1,..g};let((denied,heap),_)=with_effect(short,1<<20,&mut None,|e|observe(||projection.take(e).unwrap()));assert!(denied.is_none());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(projection.take_demand().unwrap(),d);
  let((result,heap),_)=with_effect(g,1<<20,&mut None,|e|observe(||projection.take(e).unwrap().unwrap()));let(output,progress)=result;assert!(progress.fits(g));assert_eq!((heap.requested_bytes,heap.released_bytes),(progress.retained_capacity_bytes,progress.released_bytes));assert_eq!(serde_json::json!({"value":output.value}),*row);
  projection.begin_close();for turn in 0..1000{if projection.terminal_is_empty(){break}let g=grant(projection.close_demand(4096).unwrap());let step=settled(fx(g,|e|projection.close_step(e))).result.unwrap();assert!(step.progress().fits(g));assert!(turn<999)}assert!(projection.terminal_is_empty());close_typed(output);
  for turn in 0..1000{if source.terminal_is_empty(){break}let g=RetainedCloneGrant{maximum_copy_bytes:4096,..grant(source.next_close_demand(4096).unwrap())};assert!(settled(fx(g,|e|source.close_step(e))).result.unwrap().progress().fits(g));assert!(turn<999)}assert!(source.terminal_is_empty());
 }
}

